    },
    {
      "hunk_id": "H006",
      "decision": "BASE",
      "reason": "The source says accepted common sense collapsed, not merely their idea of what was possible."
    },
    {
      "hunk_id": "H007",
      "decision": "BASE",
      "reason": "The sound effect is a roar; “Rooooom” changes the sound category."
    },
    {
      "hunk_id": "H008",
      "decision": "SOL",
      "reason": "The participial phrasing preserves the steel rain stopping without changing the action."
    },
    {
      "hunk_id": "H009",
      "decision": "SOL",
      "reason": "“Gripped them all” and “emerged” preserve the silence, shock, and reveal."
    },
    {
      "hunk_id": "H010",
      "decision": "SOL",
      "reason": "The pronoun keeps the demon accusation while avoiding an awkward repetition."
    },
    {
      "hunk_id": "H011",
      "decision": "BASE",
      "reason": "“Spat out” preserves the forceful delivery in 토해 냈다; “gave voice” softens it."
    },
    {
      "hunk_id": "H012",
      "decision": "SOL",
      "reason": "The concise phrasing keeps the Skeleton King’s smirk and gaze."
    },
    {
      "hunk_id": "H013",
      "decision": "BASE",
      "reason": "Korean says “let’s finish this”; “we should” weakens the direct suggestion."
    },
    {
      "hunk_id": "H014",
      "decision": "SOL",
      "reason": "“Wounds large and small” retains the source’s range in natural English."
    },
    {
      "hunk_id": "H015",
      "decision": "SOL",
      "reason": "“His injuries were the last thing on his mind” preserves his disregard for them."
    },
    {
      "hunk_id": "H016",
      "decision": "SOL",
      "reason": "“Anyone” preserves the incredulous question without changing its meaning."
    },
    {
      "hunk_id": "H017",
      "decision": "BASE",
      "reason": "The source explicitly says he muttered; SOL drops that speech action."
    },
    {
      "hunk_id": "H018",
      "decision": "SOL",
      "reason": "The phrasing clearly conveys that he sees the blood and corpses left by the whirlwind."
    },
    {
      "hunk_id": "H019",
      "decision": "SOL",
      "reason": "The reserve force and Amir’s status as commander and finest warrior remain intact."
    },
    {
      "hunk_id": "H020",
      "decision": "SOL",
      "reason": "“Had been with them” naturally conveys that Amir was among the force."
    },
    {
      "hunk_id": "H021",
      "decision": "SOL",
      "reason": "“Killed by one man” preserves the disbelief and the source’s meaning."
    },
    {
      "hunk_id": "H022",
      "decision": "SOL",
      "reason": "The repeated “impossible” retains both disbelief and incomprehension."
    },
    {
      "hunk_id": "H023",
      "decision": "SOL",
      "reason": "The revised phrasing preserves the trembling hand and groan."
    },
    {
      "hunk_id": "H024",
      "decision": "SOL",
      "reason": "The cut-off word still communicates the interrupted “impossible.”"
    },
    {
      "hunk_id": "H025",
      "decision": "SOL",
      "reason": "The one-word reply preserves the Skeleton King’s abrupt interruption."
    },
    {
      "hunk_id": "H026",
      "decision": "SOL",
      "reason": "The sentence keeps the wavering voice abruptly cut off."
    },
    {
      "hunk_id": "H027",
      "decision": "SOL",
      "reason": "The guillotine image and even delivery are retained in natural phrasing."
    },
    {
      "hunk_id": "H028",
      "decision": "SOL",
      "reason": "Present-tense “can” suits the claim about Jin Taekyung’s ability."
    },
    {
      "hunk_id": "H029",
      "decision": "SOL",
      "reason": "The eyes-blazing description preserves the man’s anger."
    },
    {
      "hunk_id": "H030",
      "decision": "SOL",
      "reason": "The aura and killing intent still emanate from him and engulf the space."
    },
    {
      "hunk_id": "H031",
      "decision": "SOL",
      "reason": "The pressure conveys that an ordinary Hunter could barely breathe."
    },
    {
      "hunk_id": "H032",
      "decision": "SOL",
      "reason": "“More familiar than anything else” preserves the undead’s familiarity with killing intent."
    },
    {
      "hunk_id": "H033",
      "decision": "BASE",
      "reason": "The source says he was in contact with death; “stood close” weakens that image."
    },
    {
      "hunk_id": "H034",
      "decision": "SOL",
      "reason": "The man’s aura remains the comparison to the undead’s familiar energy."
    },
    {
      "hunk_id": "H035",
      "decision": "SOL",
      "reason": "“If I’m generous” naturally captures 잘 쳐줘야."
    },
    {
      "hunk_id": "H036",
      "decision": "BASE",
      "reason": "실소 conveys a snort or derisive chuckle; “quiet laugh” loses that attitude."
    },
    {
      "hunk_id": "H037",
      "decision": "SOL",
      "reason": "The split sentence removes repetition while retaining the contrast."
    },
    {
      "hunk_id": "H038",
      "decision": "BASE",
      "reason": "The source explicitly says he would have angered “that guy”; SOL replaces the pointed reference with “him.”"
    },
    {
      "hunk_id": "H039",
      "decision": "BASE",
      "reason": "SOL drops the source’s repeated “God” and the description of God as great."
    },
    {
      "hunk_id": "H040",
      "decision": "BASE",
      "reason": "Korean says he looked around while echoing the words; SOL omits the echo."
    },
    {
      "hunk_id": "H041",
      "decision": "SOL",
      "reason": "“Corpses lay in every direction” preserves the scene without an unnecessary ground reference."
    },
    {
      "hunk_id": "H042",
      "decision": "SOL",
      "reason": "“Surely this isn’t” captures the source’s incredulous rhetorical question."
    },
    {
      "hunk_id": "H043",
      "decision": "SOL",
      "reason": "The conditional recast keeps the Skeleton King’s sardonic concession."
    },
    {
      "hunk_id": "H044",
      "decision": "SOL",
      "reason": "The line naturally specifies that the magically empowered voice reached both groups."
    },
    {
      "hunk_id": "H045",
      "decision": "SOL",
      "reason": "SOL already says the voice reached Hunters and fanatics, preserving the deleted sentence’s meaning."
    },
    {
      "hunk_id": "H046",
      "decision": "SOL",
      "reason": "The cold-water image and the Hunters taking up weapons again preserve the source’s effect."
    },
    {
      "hunk_id": "H047",
      "decision": "SOL",
      "reason": "The shift from one human to many follows the source’s deliberate correction."
    },
    {
      "hunk_id": "H048",
      "decision": "SOL",
      "reason": "“Since coming into the world” preserves the timeline and reads naturally."
    },
    {
      "hunk_id": "H049",
      "decision": "SOL",
      "reason": "“Kept dying” and “didn’t fight only” preserve the repeated deaths and contrast."
    },
    {
      "hunk_id": "H050",
      "decision": "BASE",
      "reason": "The source says they had values worth protecting; “things” makes that more generic."
    },
    {
      "hunk_id": "H051",
      "decision": "BASE",
      "reason": "The source says he could not accept that different kinds of death existed, not that they might exist."
    },
    {
      "hunk_id": "H052",
      "decision": "SOL",
      "reason": "“More closely than any other monster” preserves the comparison clearly."
    },
    {
      "hunk_id": "H053",
      "decision": "SOL",
      "reason": "“Stood beside them” preserves the Skeleton King’s companionship with humans."
    },
    {
      "hunk_id": "H054",
      "decision": "SOL",
      "reason": "“At last” preserves the realization and its timing."
    },
    {
      "hunk_id": "H055",
      "decision": "SOL",
      "reason": "The line preserves the realization that these deaths could not all simply be called deaths."
    },
    {
      "hunk_id": "H056",
      "decision": "SOL",
      "reason": "“Lovers” accurately renders 연인 and keeps the contrast with friends."
    },
    {
      "hunk_id": "H057",
      "decision": "SOL",
      "reason": "“Died away” preserves the image of lives fading after burning brightly."
    },
    {
      "hunk_id": "H058",
      "decision": "SOL",
      "reason": "“Went forward prepared to die” preserves the source’s resolve."
    },
    {
      "hunk_id": "H059",
      "decision": "BASE",
      "reason": "SOL drops the explicit image of fighting without retreat even in the face of death."
    },
    {
      "hunk_id": "H060",
      "decision": "BASE",
      "reason": "허상 is an illusion; “falsehood” changes the source’s image."
    },
    {
      "hunk_id": "H061",
      "decision": "BASE",
      "reason": "숨을 삼켰다 means he swallowed a breath; “caught his breath” changes the physical reaction."
    },
    {
      "hunk_id": "H062",
      "decision": "SOL",
      "reason": "“Wandering gaze” preserves the directionless, wavering look."
    },
    {
      "hunk_id": "H063",
      "decision": "SOL",
      "reason": "The fragment connects naturally to the resentment and confusion described immediately before it."
    },
    {
      "hunk_id": "H064",
      "decision": "BASE",
      "reason": "The source describes some followers; SOL’s “they” can imply all of them."
    },
    {
      "hunk_id": "H065",
      "decision": "BASE",
      "reason": "The source stumbles through three repetitions of “I”; SOL removes one."
    },
    {
      "hunk_id": "H066",
      "decision": "BASE",
      "reason": "The source says he wanted to shout at those people; SOL adds that their faith was wavering."
    },
    {
      "hunk_id": "H067",
      "decision": "BASE",
      "reason": "“Silver tongue” preserves the source’s image of a demon’s persuasive speech."
    },
    {
      "hunk_id": "H068",
      "decision": "SOL",
      "reason": "“Gone blank” naturally conveys the whitened mind, while retaining the repeated words."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "The recast preserves the involuntary clenching, broken molar, and dreamlike distance."
    },
    {
      "hunk_id": "H070",
      "decision": "BASE",
      "reason": "The source says corpses filled every direction; SOL narrows this to the ground around him."
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "The singular pool matches the source’s 피 웅덩이."
    },
    {
      "hunk_id": "H072",
      "decision": "SOL",
      "reason": "The phrasing preserves the expected green, beautiful promised land."
    },
    {
      "hunk_id": "H073",
      "decision": "SOL",
      "reason": "“Almighty God” preserves the source’s description of an omnipotent God."
    },
    {
      "hunk_id": "H074",
      "decision": "SOL",
      "reason": "The recast preserves the question he swallowed rather than spoke."
    },
    {
      "hunk_id": "H075",
      "decision": "SOL",
      "reason": "“Dreamlike haze” and “brightened the darkness” preserve the vision and light."
    },
    {
      "hunk_id": "H076",
      "decision": "SOL",
      "reason": "The sentence retains the man’s forgetting who held the sword."
    },
    {
      "hunk_id": "H077",
      "decision": "SOL",
      "reason": "The sword, its chosen-only brilliance, and the man’s question to the demon remain clear."
    },
    {
      "hunk_id": "H078",
      "decision": "BASE",
      "reason": "The source says everything had stopped; “seemed to have stopped” adds uncertainty."
    },
    {
      "hunk_id": "H079",
      "decision": "SOL",
      "reason": "“Turned in the same direction” preserves the action without an unnecessary head detail."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "The recast preserves that only Amir knew the name and the man could not know it."
    },
    {
      "hunk_id": "H081",
      "decision": "SOL",
      "reason": "“Telling yourselves” preserves their belief that everything was God’s will."
    },
    {
      "hunk_id": "H082",
      "decision": "SOL",
      "reason": "“Strode forward” naturally conveys his rough, forceful advance."
    },
    {
      "hunk_id": "H083",
      "decision": "SOL",
      "reason": "The pool still splashes in every direction, and the blood-covered young man ignores it."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "The past-perfect tense fits the recollection of disasters that had already happened."
    },
    {
      "hunk_id": "H085",
      "decision": "SOL",
      "reason": "“Families had vanished” preserves the source’s image of families disappearing in the disasters."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "“People had caused it” clearly preserves that the disasters were man-made."
    },
    {
      "hunk_id": "H087",
      "decision": "BASE",
      "reason": "The source calls a god who watches over them an idiot; SOL changes the insult to not being stupid enough."
    },
    {
      "hunk_id": "H088",
      "decision": "BASE",
      "reason": "씹어 뱉듯이 conveys spitting out each word; SOL drops that forceful delivery."
    },
    {
      "hunk_id": "H089",
      "decision": "SOL",
      "reason": "“Staggered in shock” preserves their unsteady reaction and the others’ belated realization."
    },
    {
      "hunk_id": "H090",
      "decision": "SOL",
      "reason": "The counterfactual retains the point that a few words could not have changed their hearts."
    },
    {
      "hunk_id": "H091",
      "decision": "BASE",
      "reason": "The source is a direct exclamation at the heretic; SOL adds “say such a thing.”"
    },
    {
      "hunk_id": "H092",
      "decision": "SOL",
      "reason": "“Rushed him” makes the attack target clear from context without changing the action."
    },
    {
      "hunk_id": "H093",
      "decision": "SOL",
      "reason": "“Yeah” preserves 그래 and the blunt, approving reply."
    },
    {
      "hunk_id": "H094",
      "decision": "SOL",
      "reason": "The blades and bodies remain the objects pierced and sliced."
    },
    {
      "hunk_id": "H095",
      "decision": "SOL",
      "reason": "“Only then” preserves the timing of the survivors’ realization."
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "“Earlier whirlwind” preserves the reference without changing the event."
    },
    {
      "hunk_id": "H097",
      "decision": "SOL",
      "reason": "“Caught within its reach” preserves who was struck by the whirlwind."
    },
    {
      "hunk_id": "H098",
      "decision": "SOL",
      "reason": "The eerie noise still fills an area more than ten meters across."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "The revised phrasing preserves the arrows and daggers reversing course and killing their owners."
    },
    {
      "hunk_id": "H100",
      "decision": "SOL",
      "reason": "The shorter phrasing retains the dying-gasp image."
    },
    {
      "hunk_id": "H101",
      "decision": "SOL",
      "reason": "“Beyond recognition” preserves that half the attackers were torn apart beyond identification."
    },
    {
      "hunk_id": "H102",
      "decision": "BASE",
      "reason": "The source’s image is body parts filling the empty places left by screams; SOL generalizes this to silence."
    },
    {
      "hunk_id": "H103",
      "decision": "SOL",
      "reason": "The line preserves Hamid’s wide-eyed stare and the sword hilt slipping from his hand."
    },
    {
      "hunk_id": "H104",
      "decision": "SOL",
      "reason": "The lowered sword and Magic Johnson standing in midair remain clear."
    },
    {
      "hunk_id": "H105",
      "decision": "BASE",
      "reason": "Korean says “at this very moment”; SOL’s “that moment” weakens the immediacy."
    },
    {
      "hunk_id": "H106",
      "decision": "SOL",
      "reason": "“Pass judgment or grant forgiveness” preserves both roles naturally."
    },
    {
      "hunk_id": "H107",
      "decision": "SOL",
      "reason": "The plea, trembling voice, and desperate need to survive remain intact."
    },
    {
      "hunk_id": "H108",
      "decision": "SOL",
      "reason": "“Let go of his sword” preserves the action before he kneels."
    },
    {
      "hunk_id": "H109",
      "decision": "SOL",
      "reason": "“Threw his faith into the trash” retains the shattered faith and trash image."
    },
    {
      "hunk_id": "H110",
      "decision": "SOL",
      "reason": "The unwavering look and sudden reach remain intact."
    },
    {
      "hunk_id": "H111",
      "decision": "BASE",
      "reason": "“Searing” preserves the heat’s intensity; SOL reduces it to ordinary heat."
    },
    {
      "hunk_id": "H112",
      "decision": "BASE",
      "reason": "온순하게 means quietly or gently; “without resistance” invents a physical reaction."
    },
    {
      "hunk_id": "H113",
      "decision": "BASE",
      "reason": "SOL’s exclamation mark adds emphasis not present in the source sound effect."
    },
    {
      "hunk_id": "H114",
      "decision": "SOL",
      "reason": "The recast makes clear that weapons fell and people knelt on the blood-soaked sand."
    },
    {
      "hunk_id": "H115",
      "decision": "SOL",
      "reason": "“Dim light of dawn” preserves 어스름한 새벽녘."
    },
    {
      "hunk_id": "H116",
      "decision": "SOL",
      "reason": "“Looking west” preserves the direction of Jin Taekyung’s gaze and the lingering darkness."
    }
  ]
}

